// Moore state machine, one bit outputs for each state, generated by
// automatically-generated combinational multiplexers. All inputs and
// outputs are one-bit.
module TopModule(
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  input  dig,
  output reg walk_left,
  output reg walk_right,
  output reg aaah,
  output reg digging
);
  reg [2:0] state;
  reg [2:0] next_state;
  always @(*) begin
    case (state)
      3'd0: begin // walking left
        next_state = (ground & ~dig) ? 3'd1 : (bump_right ? 3'd2 : 3'd0);
        walk_left = 1; walk_right = 0; aaah = 0; digging = 0;
      end
      3'd1: begin // walking right
        next_state = (ground & ~dig) ? 3'd0 : (bump_left ? 3'd3 : 3'd1);
        walk_left = 0; walk_right = 1; aaah = 0; digging = 0;
      end
      3'd2: begin // bumped on the right, walking left
        next_state = (ground & ~dig) ? 3'd1 : (bump_right ? 3'd2 : 3'd0);
        walk_left = 1; walk_right = 0; aaah = 0; digging = 0;
      end
      3'd3: begin // bumped on the left, walking right
        next_state = (ground & ~dig) ? 3'd0 : (bump_left ? 3'd3 : 3'd1);
        walk_left = 0; walk_right = 1; aaah = 0; digging = 0;
      end
      default: begin // aaah phase, possibly during a digging transition
        next_state = (ground & ~dig) ? state[2:1] : 2'b11;
        walk_left = 0; walk_right = 0; aaah = 1; digging = 0;
      end
    endcase
  end
  always @(posedge clk) begin
    if (areset) state <= 3'd0;
    else state <= next_state;
  end
  always @(posedge clk) begin
    if (state == 3'd3 || state == 3'd2) digging <= dig;
  end
endmodule

