// One-bit finite state machine for the Lemming game. One cycle per state
// transition, combinational outputs (regardless of the state) combined
// with a separate combinational output (aaah) that changes on the same
// cycle as the transition.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state, next_state;
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else state <= next_state;
    end
    always @* begin
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        digging = 1'b0;
        case (state)
            2'b00: begin // walking left
                walk_left = 1'b1;
                if (bump_left) next_state = 2'b10;
                else if (bump_right) next_state = 2'b01;
                else if (ground) next_state = 2'b00;
                else begin aaah = 1'b1; next_state = 2'b00; end
            end
            2'b01: begin // walking right
                walk_right = 1'b1;
                if (bump_left) next_state = 2'b10;
                else if (bump_right) next_state = 2'b01;
                else if (ground) next_state = 2'b01;
                else begin aaah = 1'b1; next_state = 2'b01; end
            end
            2'b10: begin // falling/digging
                if (ground) begin
                    if (dig) begin
                        digging = 1'b1;
                        if (!bump_left && !bump_right) next_state = 2'b00;
                        else next_state = 2'b10;
                    end else begin aaah = 1'b1; next_state = 2'b00; end
                end
                else begin aaah = 1'b1; next_state = 2'b10; end
            end
            default: next_state = 2'b00;
        endcase
    end
    always @(posedge clk) begin
        if (areset) walk_left <= 1'b1;
        else if (state == 2'b00) walk_left <= 1'b1;
        else if (state == 2'b10 && !ground) walk_left <= 1'b1;
        else walk_left <= 1'b0;
    end
    always @(posedge clk) begin
        if (areset) walk_right <= 1'b0;
        else if (state == 2'b01) walk_right <= 1'b1;
        else if (state == 2'b10 && !ground) walk_right <= 1'b1;
        else walk_right <= 1'b0;
    end
endmodule

