    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            2'b00: next_state = ground ? 2'b01 : 2'b00;
            2'b01: next_state = (bump_left | dig) ? 2'b10 :
                                 (bump_right | dig) ? 2'b00 : 2'b01;
            2'b10: next_state = (bump_right | dig) ? 2'b01 :
