    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);
    // Declare the states
    localparam WALK_LEFT  = 2'b00;
    localparam WALK_RIGHT = 2'b01;
    localparam FALL        = 2'b10;
    localparam DIG         = 2'b11;
    // Declare the registers and wires
    reg [1:0] state, next_state;
    reg [1:0] next_state_reg;
    reg [1:0] state_reg;
    wire walk_left_reg;
    wire walk_right_reg;
    wire aaah_reg;
    wire digging_reg;
    // Combinational logic for the next state
    always @* begin
        case (state)
            WALK_LEFT:  next_state = bump_left     ? WALK_RIGHT :
                                     ground         ? FALL       :
                                     dig            ? DIG        :
                                                     WALK_LEFT;
            WALK_RIGHT: next_state = bump_right    ? WALK_LEFT :
                                     ground         ? FALL       :
