            default:    next_state = WALK_LEFT;
        endcase
    end
    // Sequential logic for the registers
    always @(posedge clk) begin
        if (areset) begin
            state <= WALK_LEFT;
            next_state_reg <= WALK_LEFT;
            state_reg <= WALK_LEFT;
        end else begin
            state <= next_state;
            next_state_reg <= next_state;
            state_reg <= state;
        end
    end
    // Combinational logic for the outputs
    assign walk_left_reg = (state == WALK_LEFT);
    assign walk_right_reg = (state == WALK_RIGHT);
    assign aaah_reg = (state == FALL);
    assign digging_reg = (state == DIG);
    // Register the outputs (to allow for combinational next state)
    always @(posedge clk) begin
        walk_left <= walk_left_reg;
        walk_right <= walk_right_reg;
        aaah <= aaah_reg;
        digging <= digging_reg;
    end
