            2'b01: next_state = bump_left   ? 2'b10 : bump_right ? 2'b00 : ground ? 2'b01 : dig ? 2'b11 : 2'b01;
            2'b10: next_state = bump_left   ? 2'b00 : bump_right ? 2'b01 : ground ? 2'b10 : dig ? 2'b11 : 2'b10;
            2'b11: next_state = bump_left   ? 2'b10 : bump_right ? 2'b01 : ground ? 2'b00 : dig ? 2'b11 : 2'b11;
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else state <= next_state;
    end
    always @(*) begin
        walk_left  = (state == 2'b00);
        walk_right = (state == 2'b01);
        aaah       = ground & ~(state[0] ^ state[1]);
        digging    = dig & ground;
    end
endmodule
